-- ----------------------------------------------------------------------------
-- systems: Each row is a fractal or power-law system described in a common schema.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS systems (
  system_id                           TEXT                 PRIMARY KEY          -- Primary key for the system.
);
ALTER TABLE systems ADD COLUMN IF NOT EXISTS display_name TEXT;                                     -- Human readable label.
ALTER TABLE systems ADD COLUMN IF NOT EXISTS class TEXT;                                            -- High-level class: 'fractal' or 'power_law'.
ALTER TABLE systems ADD COLUMN IF NOT EXISTS base_scale NUMERIC;                                    -- Reference scale x0 for iteration 0.
ALTER TABLE systems ADD COLUMN IF NOT EXISTS scale_factor NUMERIC;                                  -- Multiplicative change in scale per iteration.
ALTER TABLE systems ADD COLUMN IF NOT EXISTS measure_name TEXT;                                     -- What the measured quantity represents (count, perimeter, frequency, etc.).
ALTER TABLE systems ADD COLUMN IF NOT EXISTS fractal_dimension NUMERIC;                             -- Fractal (Hausdorff / similarity) dimension where defined (geometric fractals). Null for purely statistical laws.
ALTER TABLE systems ADD COLUMN IF NOT EXISTS theoretical_log_log_slope NUMERIC;                     -- Theoretical slope d(log Measure)/d(log Scale) for this system under the chosen definition of Scale.
COMMENT ON TABLE systems IS 'Each row is a fractal or power-law system described in a common schema.';
