COMMENT ON COLUMN systems.fractal_dimension IS 'Fractal (Hausdorff / similarity) dimension where defined (geometric fractals). Null for purely statistical laws.';
COMMENT ON COLUMN systems.theoretical_log_log_slope IS 'Theoretical slope d(log Measure)/d(log Scale) for this system under the chosen definition of Scale.';

-- ----------------------------------------------------------------------------
-- scales: Generic log–log points for each system at multiple iterations / scales.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS scales (
  scale_id                            TEXT                 PRIMARY KEY          -- Primary key for this scale measurement.
);
ALTER TABLE scales ADD COLUMN IF NOT EXISTS "system" TEXT;                                          -- FK to systems table.
ALTER TABLE scales ADD COLUMN IF NOT EXISTS iteration INTEGER;                                      -- Discrete zoom level or rank index.
ALTER TABLE scales ADD COLUMN IF NOT EXISTS measure NUMERIC;                                        -- Y-axis measured quantity at this scale.
ALTER TABLE scales ADD COLUMN IF NOT EXISTS is_projected BOOLEAN;                                   -- True if this data point is a projection/estimate rather than measured data.
ALTER TABLE scales ADD COLUMN IF NOT EXISTS data_regime TEXT;                                       -- Data regime for this point: 'ideal' (constructed/projection) or 'measured' (noisy real-world measurement).
ALTER TABLE scales ADD COLUMN IF NOT EXISTS measurement_model TEXT;                                 -- Optional FK to measurement_models describing noise/cutoff/discretization used to generate or interpret this point.
COMMENT ON TABLE scales IS 'Generic log–log points for each system at multiple iterations / scales.';
COMMENT ON COLUMN scales.scale_id IS 'Primary key for this scale measurement.';
COMMENT ON COLUMN scales."system" IS 'FK to systems table.';
COMMENT ON COLUMN scales.iteration IS 'Discrete zoom level or rank index.';
COMMENT ON COLUMN scales.measure IS 'Y-axis measured quantity at this scale.';
COMMENT ON COLUMN scales.is_projected IS 'True if this data point is a projection/estimate rather than measured data.';
COMMENT ON COLUMN scales.data_regime IS 'Data regime for this point: ''ideal'' (constructed/projection) or ''measured'' (noisy real-world measurement).';
COMMENT ON COLUMN scales.measurement_model IS 'Optional FK to measurement_models describing noise/cutoff/discretization used to generate or interpret this point.';

-- ----------------------------------------------------------------------------
