-- ----------------------------------------------------------------------------
-- measurement_models: Measurement/de-idealization specs used to produce or interpret real-world (noisy, finite-size, discretized) scale records.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS measurement_models (
  measurement_model_id                TEXT                 PRIMARY KEY          -- Primary key for this measurement model.
);
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS "system" TEXT;                              -- FK to systems table (measurement model is typically system-specific).
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS data_regime TEXT;                           -- Regime this model describes. Usually 'measured'.
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS scale_regime TEXT;                          -- Optional RegimeID this measurement model applies to
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS noise_type TEXT;                            -- Noise model applied to measures (e.g., lognormal multiplicative).
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS noise_sigma NUMERIC;                        -- Noise strength parameter (e.g., sigma in log space for lognormal).
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS cutoff_min_scale NUMERIC;                   -- Minimum scale included (finite-size / censoring lower bound).
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS cutoff_max_scale NUMERIC;                   -- Maximum scale included (finite-size / censoring upper bound).
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS discretization_type TEXT;                   -- How observations are discretized (none, rounding, binning, log-binning).
ALTER TABLE measurement_models ADD COLUMN IF NOT EXISTS discretization_param TEXT;                  -- Parameterization of discretization (e.g., decimals=2 or binwidth=log2).
COMMENT ON TABLE measurement_models IS 'Measurement/de-idealization specs used to produce or interpret real-world (noisy, finite-size, discretized) scale records.';
COMMENT ON COLUMN measurement_models.measurement_model_id IS 'Primary key for this measurement model.';
COMMENT ON COLUMN measurement_models."system" IS 'FK to systems table (measurement model is typically system-specific).';
COMMENT ON COLUMN measurement_models.data_regime IS 'Regime this model describes. Usually ''measured''.';
COMMENT ON COLUMN measurement_models.scale_regime IS 'Optional RegimeID this measurement model applies to';
COMMENT ON COLUMN measurement_models.noise_type IS 'Noise model applied to measures (e.g., lognormal multiplicative).';
COMMENT ON COLUMN measurement_models.noise_sigma IS 'Noise strength parameter (e.g., sigma in log space for lognormal).';
COMMENT ON COLUMN measurement_models.cutoff_min_scale IS 'Minimum scale included (finite-size / censoring lower bound).';
COMMENT ON COLUMN measurement_models.cutoff_max_scale IS 'Maximum scale included (finite-size / censoring upper bound).';
COMMENT ON COLUMN measurement_models.discretization_type IS 'How observations are discretized (none, rounding, binning, log-binning).';
COMMENT ON COLUMN measurement_models.discretization_param IS 'Parameterization of discretization (e.g., decimals=2 or binwidth=log2).';

-- ----------------------------------------------------------------------------
