ALTER TABLE observed_scales ADD COLUMN IF NOT EXISTS iteration INTEGER;                             -- Discrete zoom level or rank index.
ALTER TABLE observed_scales ADD COLUMN IF NOT EXISTS measure NUMERIC;                               -- Observed (noisy) Y-axis quantity at this scale.
ALTER TABLE observed_scales ADD COLUMN IF NOT EXISTS data_regime TEXT;                              -- Data regime. For observed_scales this is 'measured'.
COMMENT ON TABLE observed_scales IS 'Noisy, finite-range, discretized observations of each system''s scaling law. Mirrors scales but with DataRegime=''measured''.';
COMMENT ON COLUMN observed_scales.observed_scale_id IS 'Primary key for this observed scale measurement.';
COMMENT ON COLUMN observed_scales."system" IS 'FK to systems table.';
COMMENT ON COLUMN observed_scales.measurement_model IS 'FK to measurement model used/assumed for this observation set.';
COMMENT ON COLUMN observed_scales.iteration IS 'Discrete zoom level or rank index.';
COMMENT ON COLUMN observed_scales.measure IS 'Observed (noisy) Y-axis quantity at this scale.';
COMMENT ON COLUMN observed_scales.data_regime IS 'Data regime. For observed_scales this is ''measured''.';

-- ----------------------------------------------------------------------------
-- inference_runs: Inference outputs (fits and residual geometry) computed from observed_scales relative to each system fixed point.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS inference_runs (
  inference_run_id                    TEXT                 PRIMARY KEY          -- Primary key for this inference run.
);
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS "system" TEXT;                                  -- FK to systems table.
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS data_regime TEXT;                               -- Regime of the fitted data (ideal/measured).
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS measurement_model TEXT;                         -- FK to measurement model used/assumed (nullable for ideal).
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS fit_method TEXT;                                -- Fitting method used (e.g., OLS on log-log).
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS point_count INTEGER;                            -- Count of observed points used in fit (measured).
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS theoretical_log_log_slope NUMERIC;              -- Fixed-point slope for the system.
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS fitted_slope NUMERIC;                           -- Estimated slope from observed data under FitMethod.
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS fitted_intercept NUMERIC;                       -- Estimated intercept in log10 space (logMeasure = intercept + slope*logScale).
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS slope_delta NUMERIC;                            -- Difference between fitted slope and fixed-point slope.
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS r2 NUMERIC;                                     -- Coefficient of determination for the log-log fit.
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS residual_rms NUMERIC;                           -- Root-mean-square residual in log10 space (vertical residuals).
