ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS orthogonal_rms NUMERIC;                         -- RMS orthogonal distance to the fitted log-log line in (logScale, logMeasure) coordinates.
ALTER TABLE inference_runs ADD COLUMN IF NOT EXISTS deviation_score NUMERIC;                        -- Composite deviation score combining residual RMS and slope delta (units: log10 + slope).
COMMENT ON TABLE inference_runs IS 'Inference outputs (fits and residual geometry) computed from observed_scales relative to each system fixed point.';
COMMENT ON COLUMN inference_runs.inference_run_id IS 'Primary key for this inference run.';
