COMMENT ON COLUMN inference_runs.residual_max_abs IS 'Maximum absolute residual in log10 space.';
COMMENT ON COLUMN inference_runs.orthogonal_rms IS 'RMS orthogonal distance to the fitted log-log line in (logScale, logMeasure) coordinates.';
